if (points.empty() || k == 0) return {};

std::vector<std::pair<double, size_t>> distIndex;
distIndex.reserve(points.size());

for (size_t i = 0; i < points.size(); ++i) {
    const Point3D& p = points[i];
    double dx = p.x - searchPoint.x;
    double dy = p.y - searchPoint.y;
    double dz = p.z - searchPoint.z;
    double dist = dx * dx + dy * dy + dz * dz;
    distIndex.emplace_back(dist, i);
}

std::nth_element(distIndex.begin(), distIndex.begin() + std::min(k, distIndex.size()) - 1, distIndex.end(),
    [](const std::pair<double, size_t>& a, const std::pair<double, size_t>& b) { return a.first < b.first; });

std::vector<size_t> result;
result.reserve(std::min(k, distIndex.size()));
for (size_t i = 0; i < std::min(k, distIndex.size()); ++i) {
    result.push_back(distIndex[i].second);
}
return result;
